local a=require("tools.simrig")local function b(c)return string.format("%5.1f",c)end;local function d(c)return c*180/math.pi end;local function e(f,g,h,i)local j=a.buildStack(f,g)local k,l=j.flight,j.sim;k:handleCommand({k="gndSafety",on=false})k:handleCommand({k="flightMode",id="CRUISE"})k:handleCommand({k="masterMode",id="CPL"})k:handleCommand({k="engage"})local m={}for n,o in ipairs(i)do local p,q,r,s=0,0,0,0;for n=1,math.floor(o.secs/h)do k:step(h,o.held,l:sensors())l:step(h)local t=l:sensors()p=math.max(p,math.abs(d(t.pitch)))q=math.max(q,math.abs(d(t.roll)))r,s=d(t.pitch),d(t.roll)end;m[o.tag]={peakP=p,peakR=q,endP=r,endR=s}end;return m end;local u={{secs=6,held={up=true},tag="climb"},{secs=3,held={},tag="s0"},{secs=6,held={surgeFwd=true},tag="surge"},{secs=3,held={surgeBack=true},tag="brake"},{secs=8,held={},tag="recover"}}local v={{secs=6,held={up=true},tag="climb"},{secs=3,held={},tag="s0"},{secs=5,held={swayRight=true},tag="strafe"},{secs=8,held={},tag="srecover"}}local function w()local x={}local function y(z)x[#x+1]=z end;local A={spoolTime=0.5,tiltTrans=1.0,latRoll=0.6,surgePitch=0.1}y("simrig isolation: post-maneuver ring (peak |pitch| after brake, peak |roll| after strafe), deg")y("params: spoolTime=0.5 tiltTrans=1.0 latRoll=0.6 surgePitch=0.1")local B={swayRoll=0.10,surgePitch=-0.05,authority=0.3}local C={swayRoll=0,surgePitch=0,authority=0.3}local D={{"COUPLED (decpl .10, brakeTrim T)",{decoupleGains=B,brakeTrim=true}},{"decouple OFF (brakeTrim T)",{decoupleGains=C,brakeTrim=true}},{"decouple OFF + brakeTrim=false",{decoupleGains=C,brakeTrim=false}},{"decouple OFF + trim OFF",{decoupleGains=C,trim=false}},{"decpl ON + trim OFF",{decoupleGains=B,trim=false}},{"ALL OFF (decpl+trim+tiltBrake)",{decoupleGains=C,trim=false,tiltBrake=false}}}for n,h in ipairs({0.1,0.2})do y("")y(string.format("=== dt=%.2f (%.0f Hz) ===",h,1/h))y(string.format("%-22s | %s | %s","config","brake->recover |pitch|","strafe->recover |roll|"))for n,E in ipairs(D)do local F=e(A,E[2],h,u)local G=e(A,E[2],h,v)y(string.format("%-22s |  brake %s  recover %s |  strafe %s  recover %s",E[1],b(F.brake.peakP),b(F.recover.peakP),b(G.strafe.peakR),b(G.srecover.peakR)))end end;local H={swayRoll=0,surgePitch=0,authority=0.3}local I={{"STRIP (no B)",{decoupleGains=H,brakeTrim=false}},{"B1 kd x3 (.66)",{decoupleGains=H,brakeTrim=false,tune={pitchKd=0.66,rollKd=0.66}}},{"B2 softer arrest ks/2",{decoupleGains=H,brakeTrim=false,tune={surgeKs=0.25,swayKs=0.25}}},{"B5 decpl swR-.10 suP-.05",{decoupleGains={swayRoll=-0.10,surgePitch=-0.05,authority=0.3},brakeTrim=false}},{"B5 decpl swR-.20 suP-.10",{decoupleGains={swayRoll=-0.20,surgePitch=-0.10,authority=0.5},brakeTrim=false}},{"B5 decpl swR-.40 suP-.20",{decoupleGains={swayRoll=-0.40,surgePitch=-0.20,authority=0.8},brakeTrim=false}}}for n,h in ipairs({0.1,0.2})do y("")y(string.format("################ B damping @ dt=%.2f (%.0f Hz), STRIP baseline ################",h,1/h))for n,E in ipairs(I)do local F=e(A,E[2],h,u)local G=e(A,E[2],h,v)y(string.format("%-26s | pitch %s | roll %s",E[1],b(F.recover.peakP),b(G.srecover.peakR)))end end;return table.concat(x,"\n")end;return{run=e,report=w,SURGE=u,STRAFE=v}